local function rebuildCross()
    if not CrossGui then return end
    for _, c in ipairs(CrossGui:GetChildren()) do c:Destroy() end
    local sz = S.CrossSize
    CrossGui.Size = UDim2.fromOffset(sz, sz)
    local col = S.CrossColor
    local style = S.CrossStyle
    local function arm(ax, ay, w, h)
        local f = Instance.new("Frame")
        f.AnchorPoint = Vector2.new(0.5, 0.5)
        f.Position = UDim2.fromScale(ax, ay)
        f.Size = UDim2.fromOffset(w, h)
        f.BackgroundColor3 = col
        f.BorderSizePixel = 0
        f.Parent = CrossGui
    end
    if style == 1 then -- +
        local t = math.max(2, math.floor(sz * 0.12))
        local l = math.floor(sz * 0.35)
        arm(0.5, 0.15, t, l)
        arm(0.5, 0.85, t, l)
        arm(0.15, 0.5, l, t)
        arm(0.85, 0.5, l, t)
    elseif style == 2 then -- x
        for _, rot in ipairs({45, -45}) do
            local f = Instance.new("Frame")
            f.AnchorPoint = Vector2.new(0.5, 0.5)
            f.Position = UDim2.fromScale(0.5, 0.5)
            f.Size = UDim2.fromOffset(math.max(2, sz * 0.12), sz * 0.7)
            f.BackgroundColor3 = col
            f.BorderSizePixel = 0
            f.Rotation = rot
            f.Parent = CrossGui
        end
    elseif style == 3 then -- dot
        local d = Instance.new("Frame")
        d.AnchorPoint = Vector2.new(0.5, 0.5)
        d.Position = UDim2.fromScale(0.5, 0.5)
        d.Size = UDim2.fromOffset(math.max(4, sz * 0.35), math.max(4, sz * 0.35))
        d.BackgroundColor3 = col
        d.BorderSizePixel = 0
        d.Parent = CrossGui
        Instance.new("UICorner", d).CornerRadius = UDim.new(1, 0)
    else -- circle
        local d = Instance.new("Frame")
        d.AnchorPoint = Vector2.new(0.5, 0.5)
        d.Position = UDim2.fromScale(0.5, 0.5)
        d.Size = UDim2.fromOffset(sz, sz)
        d.BackgroundTransparency = 1
        d.Parent = CrossGui
        Instance.new("UICorner", d).CornerRadius = UDim.new(1, 0)
        local st = Instance.new("UIStroke")
        st.Color = col
        st.Thickness = math.max(1.5, sz * 0.1)
        st.Parent = d
    end
end

RunService.RenderStepped:Connect(function()
    ensureVisual()
    local vp = Camera.ViewportSize
    local cx, cy = vp.X / 2, vp.Y / 2
    local any = S.Frenzy or S.Hidden or S.Butcher
    if S.ShowFOV and any then
        FOVFrame.Visible = true
        FOVFrame.Size = UDim2.fromOffset(S.FOV * 2, S.FOV * 2)
        FOVFrame.Position = UDim2.fromOffset(cx, cy)
        local st = FOVFrame:FindFirstChildOfClass("UIStroke")
        if st then
            st.Color = locking and Color3.fromRGB(255, 80, 120) or C.accent
            st.Transparency = locking and 0.1 or 0.35
        end
    else
        FOVFrame.Visible = false
    end
    CrossGui.Visible = any and S.ShowCross
    CrossGui.Position = UDim2.fromOffset(cx, cy)
    if CrossGui and #CrossGui:GetChildren() == 0 then rebuildCross() end
    -- tracker + lock
    local lockPlr, lockPos = nil, nil
    if locking then
        local range = S.MaxDist
        -- Hidden skill: pakai HiddenRange
        if lockSource == "Hidden" then
            range = S.HiddenRange
        end
        lockPlr, lockPos = getLockTarget(range)
        if lockPos then
            -- Jeff/Frenzy: lembut; Hidden/Butcher: agak kenceng
            local str = 0.42
            if lockSource == "Hidden" then str = 0.62
            elseif lockSource == "Butcher" then str = 0.70
            elseif lockSource == "Frenzy" then str = 0.52
            end
            Camera.CFrame = Camera.CFrame:Lerp(CFrame.new(Camera.CFrame.Position, lockPos), str)
        end
    end

    -- tracker line
    if TrackLine and TrackDot then
        if S.ShowTracker and locking and lockPos then
            local sp, on = Camera:WorldToViewportPoint(lockPos)
            if on then
                local from = Vector2.new(cx, cy)
                local to = Vector2.new(sp.X, sp.Y)
                local mid = (from + to) / 2
                local len = (to - from).Magnitude
                local ang = math.deg(math.atan2(to.Y - from.Y, to.X - from.X))
                TrackLine.Visible = true
                TrackDot.Visible = true
                TrackLine.Size = UDim2.fromOffset(len, 1)
                TrackLine.Position = UDim2.fromOffset(mid.X, mid.Y)
                TrackLine.Rotation = ang
                TrackDot.Position = UDim2.fromOffset(sp.X, sp.Y)
            else
                TrackLine.Visible = false
                TrackDot.Visible = false
            end
        else
            TrackLine.Visible = false
            TrackDot.Visible = false
        end
    end
end)

local function hookAnimator(animator)
    animator.AnimationPlayed:Connect(function(track)
        local id = track.Animation and track.Animation.AnimationId
        local src = matchLock(id, track)
        if not src then return end
        locking = true
        lockSource = src
        print("[BintangHubKiller] LOCK", src, normalizeId(id))
        task.spawn(function()
            while track.IsPlaying do task.wait(0.03) end
            locking = false
            lockSource = ""
            stickyTarget = nil
        end)
    end)
end

local function hookChar(char)
    task.spawn(function()
        local hum = char:WaitForChild("Humanoid", 8)
        if not hum then return end
        local animator = hum:FindFirstChildOfClass("Animator") or hum:WaitForChild("Animator", 5)
        if animator then hookAnimator(animator) end
    end)
end
if LP.Character then hookChar(LP.Character) end
LP.CharacterAdded:Connect(hookChar)


-- ESP highlight putih / merah knocked
local espBox = {}
local function updateESP()
    if not S.ShowESP then
        for plr, gui in pairs(espBox) do
            if gui then gui.Enabled = false end
        end
        return
    end
    for _, plr in ipairs(Players:GetPlayers()) do
        if isSurvivor(plr) and plr.Character then
            local char = plr.Character
            local hrp = char:FindFirstChild("HumanoidRootPart")
            local hum = char:FindFirstChildOfClass("Humanoid")
            if hrp and hum and hum.Health > 0 then
                local bill = espBox[plr]
                if not bill or not bill.Parent then
                    bill = Instance.new("BillboardGui")
                    bill.Name = "BH_" .. plr.Name
                    bill.AlwaysOnTop = true
                    bill.Size = UDim2.fromOffset(12, 12)
                    bill.StudsOffset = Vector3.new(0, 3, 0)
                    bill.Adornee = hrp
                    bill.Parent = ESPFolder or CoreGui
                    local dot = Instance.new("Frame")
                    dot.Name = "Dot"
                    dot.Size = UDim2.fromScale(1, 1)
                    dot.BorderSizePixel = 0
                    dot.Parent = bill
                    Instance.new("UICorner", dot).CornerRadius = UDim.new(1, 0)
                    local ring = Instance.new("UIStroke")
                    ring.Name = "Ring"
                    ring.Thickness = 1.2
                    ring.Color = Color3.new(1, 1, 1)
                    ring.Parent = dot
                    espBox[plr] = bill
                end
                bill.Enabled = true
                bill.Adornee = hrp
                local knocked = isKnocked(plr)
                local col = knocked and Color3.fromRGB(255, 55, 55) or Color3.fromRGB(255, 255, 255)
                local dot = bill:FindFirstChild("Dot")
                if dot then
                    dot.BackgroundColor3 = col
                    local ring = dot:FindFirstChild("Ring")
                    if ring then ring.Color = col end
                end
            elseif espBox[plr] then
                espBox[plr].Enabled = false
            end
        elseif espBox[plr] then
            espBox[plr].Enabled = false
        end
    end
end
RunService.RenderStepped:Connect(function()
    pcall(updateESP)
end)

