bar.Position = UDim2.fromOffset(10, 292)
bar.BackgroundColor3 = C.row
bar.BorderSizePixel = 0
bar.Parent = win
corner(bar, 4)
local fill = Instance.new("Frame")
fill.Size = UDim2.new(math.clamp((S.FOV - 40) / 260, 0, 1), 0, 1, 0)
fill.BackgroundColor3 = C.accent
fill.BorderSizePixel = 0
fill.Parent = bar
corner(fill, 4)
local knobBtn = Instance.new("TextButton")
knobBtn.Size = UDim2.fromOffset(12, 12)
knobBtn.AnchorPoint = Vector2.new(0.5, 0.5)
knobBtn.Position = UDim2.new(math.clamp((S.FOV - 40) / 260, 0, 1), 0, 0.5, 0)
knobBtn.BackgroundColor3 = Color3.new(1, 1, 1)
knobBtn.Text = ""
knobBtn.AutoButtonColor = false
knobBtn.Parent = bar
corner(knobBtn, 6)
local sliding = false
local function setFOV(x)
    local a = math.clamp((x - bar.AbsolutePosition.X) / math.max(bar.AbsoluteSize.X, 1), 0, 1)
    S.FOV = math.floor(40 + a * 260)
    fill.Size = UDim2.new(a, 0, 1, 0)
    knobBtn.Position = UDim2.new(a, 0, 0.5, 0)
    fovLabel.Text = "FOV  " .. S.FOV
end
knobBtn.InputBegan:Connect(function(i)
    if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then sliding = true end
end)
bar.InputBegan:Connect(function(i)
    if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then
        sliding = true
        setFOV(i.Position.X)
    end
end)
UserInputService.InputEnded:Connect(function(i)
    if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then sliding = false end
end)
UserInputService.InputChanged:Connect(function(i)
    if sliding and (i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch) then
        setFOV(i.Position.X)
    end
end)

