smallLabel(400, "Style")
local styles = {"+", "X", "Dot", "O"}
local styleRow = Instance.new("Frame")
styleRow.Size = UDim2.new(1, -20, 0, 24)
styleRow.Position = UDim2.fromOffset(10, 416)
styleRow.BackgroundTransparency = 1
styleRow.Parent = win
for i, name in ipairs(styles) do
    local b = Instance.new("TextButton")
    b.Size = UDim2.new(0.23, 0, 1, 0)
    b.Position = UDim2.new((i - 1) * 0.255, 0, 0, 0)
    b.BackgroundColor3 = (S.CrossStyle == i) and C.accent or C.row
    b.Text = name
    b.Font = Enum.Font.GothamBold
    b.TextSize = 11
    b.TextColor3 = C.text
    b.AutoButtonColor = false
    b.Parent = styleRow
    corner(b, 6)
    b.MouseButton1Click:Connect(function()
        S.CrossStyle = i
        for _, ch in ipairs(styleRow:GetChildren()) do
            if ch:IsA("TextButton") then ch.BackgroundColor3 = C.row end
        end
        b.BackgroundColor3 = C.accent
        rebuildCross()
    end)
end

